/**
 * Expects:
 * - Current item JSON can be:
 *    a) Plain SOAP object:
 *       { sessionMeta: {...}, participant: {...} }
 *    b) Wrapped:
 *       { output: { ...SOAP... } }
 *       { output: [ { ...SOAP... } ] }
 *       [ { ...SOAP... } ]
 *
 * - Another node "Code1" with a field `nameMapping` shaped like:
 *   {
 *     "Coach": "User 1",
 *     "Billy Bob": "User 2",
 *     "Jeff Alfredo": "User 3"
 *   }
 */

let data = JSON.parse(JSON.stringify($json));

const mappingFromCode8 = $node["When Executed by Another Workflow"]?.json?.nameMapping || {};

function looksLikeSoap(obj) {
  return obj && typeof obj === "object" &&
    (obj.sessionMeta || obj.participant);
}

/**
 * Unwrap common "output" wrappers so we always work on the inner SOAP object.
 * If input is already a plain SOAP object, this section is a no-op.
 */

// Case: [ { ...SOAP... } ]
if (Array.isArray(data) && data.length === 1 && looksLikeSoap(data[0])) {
  data = data[0];
}

// Case: { output: ... }
if (data && typeof data === "object" && data.output) {
  let inner = data.output;

  // { output: [ { ...SOAP... } ] }
  if (Array.isArray(inner) && inner.length === 1 && looksLikeSoap(inner[0])) {
    inner = inner[0];
  }

  // { output: { ...SOAP... } }
  if (looksLikeSoap(inner)) {
    data = inner;
  }
}

function invertMapping(m) {
  const out = {};
  for (const realName of Object.keys(m)) {
    const id = (m[realName] || "").toString().trim().toLowerCase();
    if (!id) continue;
    out[id] = realName; // "user 1" -> "Coach"
  }
  return out;
}

// Build: {"user 1": "Coach", "user 2": "Billy Bob", ...} (keys lowercased)
const idToRealName = invertMapping(mappingFromCode8);

// Precompile regexes for speed
const patterns = Object.entries(idToRealName).map(([idLower, realName]) => {
  const parts = idLower.split(/\s+/); // "user 1" → ["user","1"]
  const pattern = new RegExp(
    `\\b${parts[0]}\\s*${parts.slice(1).join("\\s*")}\\b`,
    "gi"
  );
  return { pattern, realName };
});

function replaceInString(s) {
  if (typeof s !== "string" || patterns.length === 0) return s;
  let out = s;
  for (const { pattern, realName } of patterns) {
    out = out.replace(pattern, realName);
  }
  return out;
}

function deepReplace(value) {
  if (value == null) return value;

  if (typeof value === "string") {
    return replaceInString(value);
  }

  if (Array.isArray(value)) {
    return value.map(deepReplace);
  }

  if (typeof value === "object") {
    const out = {};
    for (const k of Object.keys(value)) {
      out[k] = deepReplace(value[k]);
    }
    return out;
  }

  return value;
}

// 1) Replace everywhere (narratives, quotes, etc.)
let output = deepReplace(data);

// 2) Ensure structural fields are also normalized

// sessionMeta.participants: array of strings
if (output.sessionMeta?.participants && Array.isArray(output.sessionMeta.participants)) {
  output.sessionMeta.participants = output.sessionMeta.participants.map(p => {
    const key = (p || "").toString().trim().toLowerCase();
    return idToRealName[key] || replaceInString(p);
  });
}

// participant.id: single string
if (output.participant?.id) {
  const idKey = output.participant.id.toString().trim().toLowerCase();
  output.participant.id = idToRealName[idKey] || replaceInString(output.participant.id);
}

// Return updated JSON as a single, unwrapped SOAP object
return [{ json: output }];

/**
 * Expects:
 * - Current item JSON is the QA output with participant_id, notes, etc.
 * - Another node "Code1" with a field `nameMapping` shaped like:
 *   {
 *     "Coach": "User 1",
 *     "Billy Bob": "User 2", 
 *     "Jeff Alfredo": "User 3"
 *   }
 *
 * This code:
 *  - Inverts to {"user 1": "Coach", "user 2": "Billy Bob", ...} (lowercased keys).
 *  - Replaces IDs case-insensitively across the entire structure:
 *      - participant_id field
 *      - notes field and any other string content
 *  - Uses a regex that tolerates extra spaces between "user" and the number.
 */

const data = JSON.parse(JSON.stringify($json));
const mappingFromCode1 = $node["When Executed by Another Workflow"]?.json?.nameMapping || {};

function invertMapping(m) {
  const out = {};
  for (const realName of Object.keys(m)) {
    const id = (m[realName] || "").toString().trim().toLowerCase();
    if (!id) continue;
    out[id] = realName; // "user 1" -> "Coach"
  }
  return out;
}

// Build: {"user 1": "Coach", "user 2": "Billy Bob", ...} (keys lowercased)
const idToRealName = invertMapping(mappingFromCode1);

// Precompile regexes for speed: allow "user   1" (any spaces), case-insensitive, word boundaries
const patterns = Object.entries(idToRealName).map(([idLower, realName]) => {
  // Split "user 1" → ["user","1"]
  const parts = idLower.split(/\s+/);
  // Build pattern "user\s*1" and wrap with word boundaries
  const pattern = new RegExp(`\\b${parts[0]}\\s*${parts.slice(1).join("\\s*")}\\b`, "gi");
  return { pattern, realName };
});

function replaceInString(s) {
  if (typeof s !== "string" || patterns.length === 0) return s;
  let out = s;
  for (const { pattern, realName } of patterns) {
    out = out.replace(pattern, realName);
  }
  return out;
}

function deepReplace(value) {
  if (value == null) return value;
  if (typeof value === "string") {
    return replaceInString(value);
  }
  if (Array.isArray(value)) {
    return value.map(deepReplace);
  }
  if (typeof value === "object") {
    const out = {};
    for (const k of Object.keys(value)) {
      out[k] = deepReplace(value[k]);
    }
    return out;
  }
  return value;
}

// 1) Replace everywhere (notes, flags evidence, etc.)
let output = deepReplace(data);

// 2) Ensure participant_id is also normalized (just in case it wasn't caught above)
if (output.participant_id) {
  const idKey = output.participant_id.toString().trim().toLowerCase();
  output.participant_id = idToRealName[idKey] || replaceInString(output.participant_id);
}

// Return updated JSON
return [{ json: output }];

